glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision lowp float;
in vec4 v_color;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform Border{
  vec4 borderColor;
  vec4 flatColor;
  vec2 resolution;
};
void main () {
  vec4 texColor = texture2D(texture, v_uv0);
  vec2 unit = 1.0 / resolution.xy;
  texColor *= v_color;
  if(texColor.a > 0.0)
  {
      vec4 col = vec4(0);
      for(float x = -2.0; x <= 2.0; x += 1.0)
      {
          for(float y = -2.0; y <= 2.0; y += 1.0)
          {
              if(texture2D(texture, v_uv0 + vec2(x * unit.x, y * unit.y)).a == 0.0)
              {
                  col = borderColor;
                  gl_FragColor = (texColor*texColor.a + col*col.a)/(col.a+texColor.a);
                  gl_FragColor.a = 1.0;
                  return;
              }
          }
      }
      #if USE_FLAT_COLOR
      texColor = flatColor;
      #endif
  }
  gl_FragColor = texColor;
}

